<template>
  <el-dialog :model-value="modelValue" :title="memory?'处理记忆版本与冲突':'明确记住一条（待核实）'" width="760px" class="pc-dialog" @update:model-value="close">
    <el-alert v-if="memory?.conflictReason" :title="memory.conflictReason" type="warning" :closable="false" /><p v-if="memory" class="pc-muted">原条目 {{memory.id}} · 版本 {{memory.version}} · {{memorySourceName(memory.source)}}</p>
    <el-form label-width="100px"><el-form-item label="候选记忆"><el-input v-model="content" type="textarea" :rows="5" :disabled="busy || !!result" /></el-form-item><el-form-item label="核对来源"><el-input v-model="source" :disabled="busy || !!result || !!memory" placeholder="写出用户原话或可核实文档来源" /></el-form-item></el-form>
    <template v-if="result?.status==='CONFLICT'"><el-alert title="候选与已有事实冲突，尚未保存。请明确替换一个当前版本、保留双方，或取消；不能以请求成功视为已记住。" type="warning" :closable="false" /><h3>尚未保存的候选</h3><pre class="pc-pre">{{safeText(result.entry.content)}}</pre><h3>中心返回的冲突条目</h3><article v-for="entry in result.conflicts" :key="entry.id"><p>条目 {{entry.id}} · 版本 {{entryVersion(entry) ?? '未提供，不能提交替换或共存'}} · {{memorySourceName(typeof entry.metadata?.source==='string'?entry.metadata.source:undefined)}}</p><pre class="pc-pre">{{safeText(entry.content)}}</pre></article><label class="pc-label">明确选择被替换的条目</label><el-select v-model="targetId" class="pc-wide" :disabled="busy" placeholder="请选择已核对的冲突条目，不自动选择"><el-option v-for="entry in result.conflicts" :key="entry.id" :value="entry.id" :label="`${entry.id} · 版本 ${entryVersion(entry) ?? '未知'}`" :disabled="!validEntry(entry)" /></el-select></template>
    <template v-else-if="result?.status==='DUPLICATE'"><el-alert title="相同事实已经存在，本次没有新增记忆。请核对原条目后保留它；不会自动将待核实内容改为已核实。" type="info" :closable="false" /><p>已有条目 {{result.entry.id}} · 版本 {{entryVersion(result.entry) ?? '未提供'}}</p><pre class="pc-pre">{{safeText(result.entry.content)}}</pre></template>
    <el-alert v-else-if="result" title="中心未保存候选，请保留输入并核对目标条目是否仍存在。" type="warning" :closable="false" />
    <el-alert v-if="error || localError" :title="error || localError" type="error" :closable="false" />
    <template #footer><el-button :disabled="busy" @click="close(false)">{{result?.status==='DUPLICATE'?'保留原条目并关闭':'取消，保留原条目'}}</el-button><el-button v-if="result" :disabled="busy" @click="editCandidate">返回修改候选</el-button><template v-if="result?.status==='CONFLICT'"><el-button v-hasPermi="['paicli:knowledge:manage']" :loading="busy" :disabled="!canCoexist" @click="coexist">明确保留两条</el-button><el-button v-hasPermi="['paicli:knowledge:manage']" type="primary" :loading="busy" :disabled="!target" @click="replaceConflict">按所选版本替换</el-button></template><el-button v-if="!result && memory?.status==='CONFLICT'" v-hasPermi="['paicli:knowledge:manage']" :loading="busy" :disabled="content!==memory.content" @click="coexistExisting">确认原条目共存</el-button><el-button v-if="!result" v-hasPermi="['paicli:knowledge:manage']" type="primary" :loading="busy" :disabled="!content.trim() || !source.trim()" @click="save">{{memory?'按当前版本替换':'保存待核实记忆'}}</el-button></template>
  </el-dialog>
</template>
<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {checkPermi} from '@/utils/permission'
import {memoryAction,saveMemory} from '@/api/paicli/knowledge'
import type {PcMemory,PcMemoryEntry,PcMemoryWriteResult} from '@/types/paicli'
import {memorySourceName,operationKeys,safeText} from '../model'
import {useOperations} from '../useOperations'
const props=defineProps<{modelValue:boolean;workspaceId:string;scope:'PROJECT'|'PERSONAL';memory?:PcMemory}>(),emit=defineEmits<{'update:modelValue':[value:boolean];saved:[]}>(),{busy,error,run}=useOperations(),keys=operationKeys(),content=ref(''),source=ref(''),result=ref<PcMemoryWriteResult>(),targetId=ref(''),localError=ref('')
let generation=0
function entryVersion(entry:PcMemoryEntry){const value=entry.version ?? entry.metadata?.version;return typeof value==='number'&&Number.isSafeInteger(value)&&value>0?value:undefined}
function validEntry(entry:PcMemoryEntry){return /^\d+$/.test(entry.id)&&entryVersion(entry)!==undefined}
const target=computed(()=>result.value?.conflicts.find(entry=>entry.id===targetId.value && validEntry(entry))),canCoexist=computed(()=>!!result.value?.conflicts.length&&result.value.conflicts.every(validEntry))
function close(value:boolean){if(busy.value)return;emit('update:modelValue',value)}
function editCandidate(){if(busy.value)return;result.value=undefined;targetId.value='';localError.value='';error.value=''}
function consume(value:PcMemory|PcMemoryWriteResult,g:number){if(g!==generation)return;if('entry' in value){if(!Array.isArray(value.conflicts)||!value.entry||typeof value.entry.content!=='string')throw new Error('记忆保存结果缺少候选或真实冲突条目，未关闭输入。');result.value=value;targetId.value='';emit('saved')}else{if(!/^\d+$/.test(value.id)||!Number.isSafeInteger(value.version))throw new Error('中心未返回已保存的记忆ID和版本，未关闭输入。');emit('saved');emit('update:modelValue',false)}}
async function scopedRun(g:number,operation:()=>Promise<void>){await run(async()=>{try{await operation()}catch(cause){if(g===generation)throw cause}})}
async function coexistExisting(){const memory=props.memory;if(!memory||memory.status!=='CONFLICT'||content.value!==memory.content||!checkPermi(['paicli:knowledge:manage']))return;const g=generation,intent={action:'coexist-existing',id:memory.id,version:memory.version};await scopedRun(g,async()=>{const response=await memoryAction(memory.id,'coexist',memory.version,memory.content,keys.get(intent));keys.done(intent);consume(response.data,g)})}
async function save(){if(!checkPermi(['paicli:knowledge:manage'])||!content.value.trim()||!source.value.trim()||result.value)return;const g=generation,memory=props.memory,data={workspaceId:props.workspaceId,scope:props.scope,content:content.value,source:source.value},intent={...data,id:memory?.id,version:memory?.version};await scopedRun(g,async()=>{const response=memory?await memoryAction(memory.id,'replace',memory.version,data.content,keys.get(intent)):await saveMemory(data,keys.get(intent));keys.done(intent);consume(response.data,g)})}
async function replaceConflict(){const selected=target.value;if(!selected||!checkPermi(['paicli:knowledge:manage']))return;const g=generation,data={workspaceId:props.workspaceId,scope:props.scope,content:content.value,source:source.value,replace_id:selected.id,replaceVersion:entryVersion(selected)!},intent={action:'replace-conflict',...data};await scopedRun(g,async()=>{const response=await saveMemory(data,keys.get(intent));keys.done(intent);consume(response.data,g)})}
async function coexist(){if(!canCoexist.value||!checkPermi(['paicli:knowledge:manage']))return;const g=generation,conflictVersions=Object.fromEntries(result.value!.conflicts.map(entry=>[entry.id,entryVersion(entry)!])),data={workspaceId:props.workspaceId,scope:props.scope,content:content.value,source:source.value,allowConflict:true,conflictVersions},intent={action:'coexist',...data};await scopedRun(g,async()=>{const response=await saveMemory(data,keys.get(intent));keys.done(intent);consume(response.data,g)})}
watch(()=>[props.modelValue,props.memory?.id,props.workspaceId,props.scope],()=>{generation++;content.value=props.memory?.content ?? '';source.value=props.memory?.source ?? '';result.value=undefined;targetId.value='';localError.value='';error.value=''},{immediate:true})
</script>
